@@ -0,0 +1,56 @@
+/* This provider dialog keeps DialogV2's sizing and Orchestra's existing float material. */
+[data-component="dialog-v2"] [data-slot="dialog-container"].orchestra-provider-dialog {
+  --provider-dialog-gap: 8px;
+  --provider-dialog-action: 28px;
+  --provider-dialog-focus: 2px;
+  --provider-dialog-leading: 1.4;
+  --provider-dialog-tracking: -0.025em;
+  --provider-dialog-heading-bottom: 12px;
+  border-radius: var(--orchestra-radius-xl);
+
+  [data-slot="dialog-content"] {
+    [data-slot="dialog-header"] {
+      align-items: center;
+      gap: var(--provider-dialog-gap);
+
+      [data-slot="dialog-header-title"] {
+        font-family: var(--mx-emphasis, var(--orchestra-font-family-sans));
+        font-size: var(--orchestra-font-size-2xl);
+        font-weight: 600;
+        line-height: var(--provider-dialog-leading);
+        letter-spacing: var(--provider-dialog-tracking);
+        overflow-wrap: anywhere;
+      }
+
+      :is([data-slot="dialog-close-button"], .provider-dialog-back) {
+        inline-size: var(--provider-dialog-action);
+        block-size: var(--provider-dialog-action);
+        flex: none;
+        margin-block-start: 0;
+        margin-inline-end: 0;
+        border-radius: var(--orchestra-radius-sm);
+        color: var(--mx-dim, var(--orchestra-muted));
+      }
+
+      :is([data-slot="dialog-close-button"], .provider-dialog-back):focus-visible {
+        outline: var(--provider-dialog-focus) solid var(--mx-blue, var(--orchestra-accent));
+        outline-offset: var(--provider-dialog-focus);
+      }
+    }
+  }
+
+  .provider-dialog-heading {
+    min-inline-size: 0;
+    padding-block-end: var(--provider-dialog-heading-bottom);
+  }
+
+  .provider-dialog-title {
+    min-inline-size: 0;
+    font-family: var(--mx-emphasis, var(--orchestra-font-family-sans));
+    font-size: var(--orchestra-font-size-2xl);
+    font-weight: 600;
+    line-height: var(--provider-dialog-leading);
+    letter-spacing: var(--provider-dialog-tracking);
+    overflow-wrap: anywhere;
+  }
+}

