+@container orchestra-settings-panel (max-width: 520px) {
+  .orchestra-settings .perm-tool {
+    flex-direction: column;
+    align-items: stretch;
+    gap: var(--settings-narrow-gap);
+    padding-block: var(--settings-narrow-gap);
+  }
+  .orchestra-settings .perm-tool > div:first-child {
+    min-inline-size: 0;
+    overflow-wrap: anywhere;
+  }
+  .orchestra-settings .perm-tool .tdesc,
+  .orchestra-settings .perm-tool .tnote {
+    line-height: var(--settings-copy-leading);
+  }
+  .orchestra-settings .perm-tool .seg {
+    margin-inline-start: 0;
+    display: grid;
+    grid-template-columns: repeat(3, minmax(0, 1fr));
+  }
+  .orchestra-settings .perm-tool .seg button {
+    inline-size: auto;
+    min-inline-size: 0;
+    block-size: var(--settings-control-target);
+  }
+  .orchestra-settings .mx-row[data-model] {
+    display: grid;
+    grid-template-columns: var(--settings-model-mark) minmax(0, 1fr) auto;
+    gap: var(--settings-narrow-gap);
+  }
+  .orchestra-settings .mx-row[data-model] .mx-grow {
+    grid-column: 2 / -1;
+    overflow-wrap: anywhere;
+  }
+  .orchestra-settings .mx-row[data-model] > .mx-badge,
+  .orchestra-settings .mx-row[data-model] > .mx-btn {
+    grid-column: 2;
+    grid-row: 2;
+    justify-self: start;
+  }
+  .orchestra-settings .mx-row[data-model] > .mx-btn {
+    min-block-size: var(--settings-control-target);
+  }
+  .orchestra-settings .mx-row[data-model] > .mx-toggle {
+    grid-column: 3;
+    grid-row: 2;
+    justify-self: end;
+  }
+}

